import unittest,json,subprocess,gzip,hashlib
from pathlib import Path
class EvidenceAdoptionTests(unittest.TestCase):
 def node(self,code):
  r=subprocess.run(['node','-e',"const assert=require('assert/strict'),E=require('./web_r4/loading-engine.js'),C=require('./web_r4/loading-coach.js'),c=require('./web_r4/loading-data.json');function run(s={},risk='BALANCED',i=0,period='LEVEL1'){let x=E.exampleInput(c,i);x.schema_version='lol-coach-loading-input-v3';x.preferences={risk};x.scenario={standard:'lane-standard-v1',overrides:s};const r=E.analyze(x,c);r.coach=C.evaluate(r,c,x.scenario,period);return r.coach;}"+code],capture_output=True,text=True);self.assertEqual(r.returncode,0,r.stderr[-2200:])
 def test_acquire_push_before_build_and_scenario_transition(self):
  self.node("const a=run(),b=run({wave:'BUILDING'});assert.equal(a.wave.selected_plan_id,'ACQUIRE_PUSH','neutral contest must first acquire the push');assert.equal(a.planboard.wave.plan_id,'ACQUIRE_PUSH');assert.equal(a.planboard.wave.diagram.plan_id,'ACQUIRE_PUSH');assert.equal(b.planboard.wave.plan_id,'SLOW_PUSH');assert.equal(b.wave.selected_plan_id,'SLOW_PUSH');assert(a.planboard.wave.handling.includes('평타'));assert(a.planboard.wave.next_wave.includes('처리 우위'));assert(a.knowledge_application.recommended_plan);for(const risk of ['LOSS_LIMIT','OPPORTUNITY']){const r=run({},risk);assert.equal(r.planboard.wave.plan_id,'ACQUIRE_PUSH');assert.deepEqual(a.periods,r.periods);}for(const s of [{resources:'LOW'},{wave:'UNKNOWN'},{wave:'INCOMING'},{engage:'THEIRS'},{engage:'OURS'},{engage:'UNKNOWN'}])assert.notEqual(run(s).planboard.wave.plan_id,'ACQUIRE_PUSH');assert.equal(run({engage:'THEIRS'}).knowledge_application.active,false);assert.notEqual(run({},'BALANCED',2).planboard.wave.plan_id,'ACQUIRE_PUSH');")
 def test_application_keeps_kind_scope_and_unknown_winner_separate(self):
  self.node("const a=run().knowledge_application;assert.equal(a.schema_version,'lol-coach-knowledge-application-v1');for(const k of ['recommended_plan','reason','direct_sources','conditions','exceptions','inference','open_questions'])assert(a[k]);assert(a.reviews.source_scope!==a.reviews.real_effect);assert.equal(a.reviews.real_effect,'NOT_MEASURED_N0');assert(a.evidence_kinds.includes('EXPERT_JUDGMENT'));assert(a.evidence_kinds.includes('MECHANISM_INFERENCE'));assert.equal(run().selected.metrics.ALLIN.assessment,'INSUFFICIENT');")
 def test_fiora_malphite_has_sourced_plan_not_unsupported_fallback(self):
  self.node("const a=run({},'BALANCED',1,'LEVEL3_5');assert.equal(a.matchup_id,'E','pictured matchup needs its own knowledge');assert.equal(a.supported,true);assert.equal(a.selected.metrics.SHORT.assessment,'INSUFFICIENT');assert.match(a.selected.metrics.SHORT.reason,/공략|조건/);assert.equal(a.selected.metrics.ALLIN.assessment,'INSUFFICIENT');assert.match(a.planboard.headline,/수급|마나/);assert.match(a.planboard.matchup_playbook.theirs.means,/말파이트/);assert(!/카이사|신비한 화살/.test(JSON.stringify([a.trade,a.selected.action])));assert(a.evidence.sources.some(s=>s.author.includes('Anoying')));const ids=new Set(a.evidence.claim_ids);assert(a.selected.metrics.SHORT.claim_ids.every(id=>ids.has(id))); ")
 def test_fiora_period_and_wave_flow_keep_learned_spells_and_resource_costs(self):
  self.node("const one=run({},'BALANCED',1),six=run({},'BALANCED',1,'LEVEL6'),buy=run({},'BALANCED',1,'FIRST_PURCHASE');assert(!/응수\\(W\\).*사용|응수\\(W\\).*막는다/.test(one.selected.action),'Lv1 Q example cannot use W');assert.match(six.trade.ours.end.join(' '),/응수|후속|이탈/);assert.match(buy.selected.reason,/덤불|방어 구매/);assert.notEqual(one.planboard.wave.combat,six.planboard.wave.combat);assert.match(buy.planboard.matchup_playbook.ours.purpose,/수급|구매/);const incoming=run({wave:'INCOMING'},'BALANCED',1);assert.equal(incoming.wave.selected_plan_id,incoming.planboard.wave.plan_id);assert.equal(incoming.diagram.plan_id,incoming.planboard.wave.plan_id);assert.equal(incoming.planboard.wave.plan_id,'TRIM_RECEIVE');")
 def test_fiora_low_unknown_trade_and_engagement_share_guarded_actions(self):
  self.node("for(const s of [{resources:'LOW'},{resources:'UNKNOWN'},{wave:'UNKNOWN'}]){const a=run(s,'OPPORTUNITY',1,'LEVEL6');for(const text of [a.trade.ours.start.join(' '),a.trade.ours.order.join(' '),...a.selected.engagements.flatMap(e=>e.order)])assert(!/대결투\\(R\\).*급소 접근/.test(text),'low/unknown must not keep R pressure order');}const a=run({},'BALANCED',1);for(const risk of ['LOSS_LIMIT','OPPORTUNITY'])assert.equal(run({},risk,1).selection.id,a.selection.id);const k=structuredClone(require('./web_r4/loading-knowledge.json'));delete k.knowledge_applications.E;const cat={...c,coaching_knowledge:k},x=E.exampleInput(cat,1),u=E.analyze(x,cat).coach;assert.equal(u.supported,false);assert(!/신비한 화살|비전 이동/.test(u.trade.ours.order.join(' '))); ")
 def test_fiora_inference_does_not_bypass_unknown_patch_preference_or_other_opponent(self):
  self.node("const a=run({},'BALANCED',1,'LEVEL3_5');for(const risk of ['LOSS_LIMIT','OPPORTUNITY'])assert.deepEqual(a.periods,run({},risk,1,'LEVEL3_5').periods);for(const s of [{resources:'UNKNOWN'},{resources:'LOW'},{enemy_key:'UNKNOWN'},{enemy_key:'SPENT'}])assert.equal(run(s,'BALANCED',1,'LEVEL3_5').selected.metrics.SHORT.assessment,'INSUFFICIENT');const x=E.exampleInput(c,1);x.enemies.find(v=>v.position==='TOP').champion='Ornn';assert.equal(E.analyze(x,c).coach.supported,false);x.enemies.find(v=>v.position==='TOP').champion='Malphite';x.patch='1.1';assert.equal(E.analyze(x,c).coach.selected.metrics.SHORT.assessment,'INSUFFICIENT');")
 def test_statistics_are_scoped_and_do_not_backfill_matchup_from_role(self):
  self.node("const a=run().knowledge_application.statistics,d=run({},'BALANCED',4).knowledge_application.statistics;assert.equal(a.matchup.pair[0],'Caitlyn');assert.equal(a.matchup.position,'BOTTOM');assert.equal(a.matchup.points.length,0);assert(a.role_context.points.length>0);assert.equal(a.role_context.comparison,'ROLE_POPULATION_RATE');assert.equal(a.duo_verified,false);assert.equal(d.matchup.pair[0],'Ezreal');assert(d.matchup.points.length>0);for(const p of d.matchup.points){assert.equal(p.mean,null);assert(p.n>0);assert(p.omission_reason);}assert.equal(d.outcome.scope,'FULL_MATCH_RESULT_NOT_FIGHT_WIN');assert.equal(d.outcome.n,1);assert.equal(d.outcome.wins,1);assert(!('strength' in d.outcome));")
 def test_darius_close_contact_inference_is_not_allin_or_any_start_skill(self):
  self.node("const a=run({},'BALANCED',3),b=run({start_skill:'Q'},'BALANCED',3);assert.equal(a.selected.metrics.EXTENDED.assessment,'ALLY');assert.equal(a.selected.metrics.EXTENDED.evidence_kind,'MECHANISM_INFERENCE');assert.equal(a.selected.metrics.ALLIN.assessment,'INSUFFICIENT');assert.equal(b.selected.metrics.EXTENDED.assessment,'INSUFFICIENT');for(const risk of ['LOSS_LIMIT','OPPORTUNITY'])assert.deepEqual(a.periods,run({},risk,3).periods);assert(a.knowledge_application.exceptions.some(x=>x.includes('이탈')));assert.equal(run({resources:'LOW'},'BALANCED',3).selected.metrics.EXTENDED.assessment,'INSUFFICIENT');")
 def test_older_knowledge_does_not_inherit_new_inference_or_source_refs(self):
  self.node("const old=structuredClone(require('./web_r4/loading-knowledge.json'));delete old.knowledge_applications;delete old.statistical_context;for(const m of old.matchups)m.claims=m.claims.filter(v=>!v.application_id);const cat={...c,coaching_knowledge:old};for(const i of [0,3]){const x=E.exampleInput(cat,i),a=E.analyze(x,cat).coach;if(i===0){assert.equal(a.wave.selected_plan_id,'SLOW_PUSH');assert.equal(a.planboard.wave.plan_id,'SLOW_PUSH');}else assert.equal(a.selected.metrics.EXTENDED.assessment,'INSUFFICIENT');assert.equal(a.knowledge_application.supported,false);const ids=new Set(old.matchups.flatMap(m=>m.claims.map(v=>v.id)));assert(a.planboard.wave.claim_ids.every(id=>ids.has(id)));}")
 def test_purpose_overrides_keep_active_wave_procedure_and_diagram_consistent(self):
  self.node("for(const goal of ['FARM','RECALL']){const x=E.exampleInput(c,0);x.schema_version='lol-coach-loading-input-v4';x.preferences={risk:'BALANCED'};x.scenario={standard:'lane-standard-v1',overrides:{}};x.planning={basis:'loading-plan-example-v1',overrides:{goal,...(goal==='RECALL'?{clear_window:'OPEN'}:{})}};const a=E.analyze(x,c).coach;assert.equal(a.wave.selected_plan_id,a.planboard.wave.plan_id);assert.equal(a.wave.selected.id,a.planboard.wave.plan_id);assert.equal(a.diagram.plan_id,a.planboard.wave.plan_id);assert.notEqual(a.wave.selected_plan_id,'ACQUIRE_PUSH');}")
 def test_public_statistical_projection_preserves_archive_visibility_and_source_hash(self):
  k=json.loads(Path('web_r4/loading-knowledge.json').read_text());self.assertIn('statistical_context',k,'existing stats are not linked')
  x=k['statistical_context'];self.assertEqual(x['datasets']['power']['matches'],275)
  for source in x['datasets'].values():self.assertEqual(source['sha256'],hashlib.sha256(Path(source['local_source']).read_bytes()).hexdigest())
  raw=json.loads(gzip.decompress(Path(x['datasets']['power']['local_source']).read_bytes()))
  c=next(c for c in raw['cohorts']if c['comparison']=='MATCHUP'and c['champion']=='Ezreal'and c['opponent_champion']=='Kaisa'and c['position']=='BOTTOM'and c['metric']=='gold_delta')
  point=next(p for p in c['points']if p['minute']==10);projected=next(p for p in x['matchups']['D']['matchup']['points']if p['minute']==10 and p['metric']=='gold_delta');self.assertEqual(point['n'],projected['n']);self.assertEqual(point['visible'],projected['legacy_visible']);self.assertIsNone(projected['mean'])
if __name__=='__main__':unittest.main()
